using Microsoft.Extensions.Diagnostics.HealthChecks;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddHealthChecks()
    // Check the database connection
    .AddDbContextCheck<AppDbContext>(name: "database")
    // Check a Redis cache connection
    .AddRedis(
        builder.Configuration.GetConnectionString("Redis") ?? "localhost:6379",
        name: "redis")
    // Custom health check for an external API
    .AddUrlGroup(
        new Uri("https://api.example.com/health"),
        name: "external-api",
        timeout: TimeSpan.FromSeconds(5));

var app = builder.Build();

// Simple health endpoint (suitable for load balancers)
app.MapHealthChecks("/health");

// Detailed health endpoint (for debugging — restrict in production)
app.MapHealthChecks("/health/detailed", new HealthCheckOptions
{
    Predicate = _ => true,
    ResponseWriter = async (context, report) =>
    {
        context.Response.ContentType = "application/json";
        var result = System.Text.Json.JsonSerializer.Serialize(new
        {
            status = report.Status.ToString(),
            checks = report.Entries.Select(e => new
            {
                name = e.Key,
                status = e.Value.Status.ToString(),
                description = e.Value.Description
            })
        });
        await context.Response.WriteAsync(result);
    }
});

app.Run();

using System.Diagnostics.Metrics;

public class OrderService(
    IOrderRepository repository,
    ILogger<OrderService> logger)
{
    // Define a meter (a collection of related metrics)
    private static readonly Meter s_meter = new(
        "MyApp.Orders",
        "1.0.0");

    // Define a counter metric
    private readonly Counter<int> _ordersProcessed = s_meter.CreateCounter<int>(
        name: "orders.processed",
        unit: "orders",
        description: "Number of orders processed");

    // Define a histogram for measuring duration
    private readonly Histogram<double> _orderDuration = s_meter.CreateHistogram<double>(
        name: "order.processing.duration",
        unit: "seconds",
        description: "Time taken to process an order");

    public async Task<Order> ProcessAsync(CreateOrderDto dto)
    {
        var stopwatch = System.Diagnostics.Stopwatch.StartNew();

        try
        {
            var order = await repository.CreateAsync(dto);

            // Record the metric
            _ordersProcessed.Add(1,
                new KeyValuePair<string, object?>([]));

            return order;
        }
        finally
        {
            stopwatch.Stop();
            // Record the duration regardless of success/failure
            _orderDuration.Record(stopwatch.Elapsed.TotalSeconds,
                new KeyValuePair<string, object?>([]));
        }
    }
}

